    // W3C SCXML 6.4: Execute pending invokes at macrostep end
    fn execute_pending_invokes(&mut self, engine: &mut Engine<Self>) {
        self.do_execute_pending_invokes(engine);
    }

    // SCE Accepted Subset 2.15, "Saving and restoring": a saved state names the
    // `<invoke>`s a declared host invoker is running, and a restore starts each
    // again from the request it saved. What it may name is what the document
    // hands to a host.
    fn host_invoke_owner(processor_type: &str, invoke_id: &str) -> Option<Self::State> {
        match (processor_type, invoke_id) {
            ("sce-host-cose-sign1", "sign") => Some(StaticHostCoseState::Signing),
            ("sce-host-cose-verify1", "verify") => Some(StaticHostCoseState::Verifying),
            ("sce-host-cose-encrypt0", "seal") => Some(StaticHostCoseState::Sealing),
            ("sce-host-cose-decrypt0", "open") => Some(StaticHostCoseState::Opening),
            ("sce-host-key-derive", "derive") => Some(StaticHostCoseState::Deriving),
            _ => None,
        }
    }

    // W3C SCXML 6.2 + 6.4: a delayed `<send target="#_parent">` whose wait is
    // over, with the payload an immediate one carries. It waited in this
    // machine's own queue, so `<cancel>` reached it and a child that ended
    // first dropped it — the engine dispatches nothing once final.
    fn deliver_to_parent(&mut self, event_name: &str, event_data: &str) -> bool {
        if let Some(ref parent_queue) = self.parent_external_queue {
            if let Ok(mut q) = parent_queue.lock() {
                q.push((event_name.to_string(), event_data.to_string()));
                return true;
            }
        }
        false
    }

    // W3C SCXML C.1: whether a session invoked this one — the queue the
    // invoking parent installs is the link to it.
    fn has_parent_session(&self) -> bool {
        self.parent_external_queue.is_some()
    }

    // W3C SCXML C.1: whether `session_id` names the session that invoked this
    // one — the location it publishes is a target, so a reply sent to the
    // origin of an event the parent sent reaches it (docs/adr/0090).
    fn is_parent_session(&self, session_id: &str) -> bool {
        self.parent_external_queue.is_some()
            && !session_id.is_empty()
            && self.parent_session_id == session_id
    }

    // docs/adr/0045: this session's own id, as a saved state holds it.
    fn own_session_id(&self) -> &str {
        self.session_id.as_deref().unwrap_or("")
    }

    // docs/adr/0045: a restored session carries on under its saved id.
    fn bind_session_id(&mut self, session_id: &str) {
        self.session_id = Some(session_id.to_string());
    }
